#include "PlantPot.h"
#include "Components/StaticMeshComponent.h"
APlantPot::APlantPot(){PrimaryActorTick.bCanEverTick=true;PotMesh=CreateDefaultSubobject<UStaticMeshComponent>(TEXT("Pot"));RootComponent=PotMesh;} bool APlantPot::Plant(EPlantType T){if(GrowthProgress>0&&GrowthProgress<1)return false;PlantedType=T;GrowthProgress=.001f;return true;} bool APlantPot::Water(float A){if(A<=0)return false;WaterLevel=FMath::Min(WaterLevel+A,100.f);return true;} int32 APlantPot::Harvest(){if(GrowthProgress<1)return 0;GrowthProgress=0;return FMath::RandRange(2,5);} void APlantPot::Tick(float D){Super::Tick(D);if(GrowthProgress<=0||GrowthProgress>=1||WaterLevel<=0)return;GrowthProgress=FMath::Min(1.f,GrowthProgress+D/FMath::Max(GrowthTime,.01f));WaterLevel=FMath::Max(0.f,WaterLevel-D*.1f);}
